INSERT INTO moment_sources (moment_id, position, title, url, publisher, retrieved_at, note) VALUES ('00000000-0000-4000-8000-00000000d0d8', '2', '1947 Twin-City Zephyr crash site', 'https://dghistory.org/twin-city-zephyr-crash-site-near-main-street-train-station/', 'Downers Grove Historical Society', '2026-11-06', 'Local commemoration; the federal investigation is the primary source for cause and casualties.');

UPDATE moments SET title = 'Morning Platform', body = 'The Main Street platform belongs to a commuter corridor with roots in the nineteenth century. Metra''s history of the BNSF line places the beginning of Chicago, Burlington & Quincy suburban passenger service in the 1860s. The Historical Society dates the original Downers Grove station to 1864, when it served a community whose agricultural business also benefited from the new railroad.

A commuter station connects two scales of life: the local streets around its platforms and the much larger city at the other end of the journey. In Downers Grove, that connection helped define the village center. The station''s history is consequently about daily movement as well as famous trains or individual accidents. Repeated trips to work and home made the railway an enduring part of how residents used the village.

The equipment and companies carrying those trips changed over time. Metra''s historical account describes the introduction of a fully dieselized locomotive fleet and stainless-steel, two-level passenger coaches in the early 1950s. The Chicago, Burlington & Quincy became part of Burlington Northern in 1970. The later merger with the Atchison, Topeka & Santa Fe in 1995 created the BNSF Railway. Those corporate names trace changes in the rail system rather than separate beginnings for the place itself.

The accompanying photograph was taken by David Wilson in May 2004. It shows the station in the era of Metra commuter service and makes the relationship between platforms, tracks and surrounding town visible. It does not establish today''s timetable, fares or passenger numbers. Those operational details change and should be checked with the operator before travel.

The station building carries part of that history in its fabric. The present passenger station dates from 1911 and replaced the original 1864 depot. The Historical Society describes its symmetrical front, pilasters and terra-cotta details as features of Classical Revival design influenced by the Beaux Arts tradition. Repairs after the 1947 accident reused original bricks while some decorative trim was lost. The platforms and building have therefore served successive railway companies and generations of passengers through changes that remain visible at the site.', hero_media_id = '00000000-0000-4000-8000-00000000f0f1', updated_at = now() WHERE id = '00000000-0000-4000-8000-00000000d0d2';

